  _ = `Tuto zprávu jste obdrželi, protože jste ve službě Steam hráli`,
  _ = `Tuto zprávu jste obdrželi, protože ve službě Steam sledujete %1$s.`,
  _ = `Tuto zprávu jste obdrželi, protože jste hráli hru ze série %1$s.`,
