  _ = `© Valve Corporation. PO Box 1688 Bellevue, WA 98009.`,
  _ = `Všechna práva vyhrazena. Všechny ochranné známky jsou vlastnictvím příslušných subjektů v USA a dalších zemích.`,
  _ = `Odeslat testovací e-mail`,
  _ = `Nepodařilo se odeslat testovací e-mail, protože Vaše adresa není ověřená. E-mailovou adresu můžete ověřit zde: %1$s`,
  _ = `Změny e-mailu nebyly uloženy. Než vyvoláte náhled e-mailu, uložte jeho změny.`,
  _ = `Odeslat e-mail na adresu %1$s přiřazenou k Vašemu účtu? Pokud tato adresa nesedí, aktualizujte ji zde: %2$s`,
  _ = `Vybrat reprezentující obrázek`,
  _ = `%1$s×%2$s px`,
  _ = `Filtrování účtů`,
  _ = `Aby uživatel obdržel tento e-mail, musí projít všemi těmito filtry.`,
  _ = `Aplikace se nachází v top X v interaktivním katalogu služby Steam`,
  _ = `Vyloučit uživatele, kteří si Vaši hru již přejí`,
  _ = `Experimentální nastavení pro vyloučení následujících:`,
