  _ = `Vyloučit vlastníky Vaší hry`,
  _ = `Vlastníci, kteří hru ještě nehráli`,
  _ = `Uživatelé, kteří sledují Vaši stránku tvůrce (%1$s)`,
  _ = `Hráči her propojených s Vaší stránou tvůrce (%1$s)`,
  _ = `S touto hrou není propojena domovská stránka tvůrce, čímž je omezen dosah e-mailu. Více informací: %1$s`,
  _ = `Obsah není kompletní pro jazyk %1$s. Je vyplněno %2$s/%3$s sekcí.`,
  _ = `E-mail vyžaduje reprezentující obrázek v angličtině, bez něhož nemůže být odeslán.`,
  _ = `Musíte vybrat nejméně jednu skupinu příjemců e-mailu`,
  _ = `Tento e-mail nemá žádný text`,
  _ = `V sekci „Příjemci“ musíte vybrat alespoň jednu z možností.`,
  _ = `Byla určena URL adresa videa z YouTube, ale nepodařilo se ji analyzovat. Zkontrolujte proto platnost adresy.`,
  _ = `E-maily nelze nastavit a odeslat, dokud není zveřejněna a zpřístupněna nadřazená událost. Nejprve tedy zveřejněte událost.`,
  _ = `E-mail je lokalizován do jazyka %1$s, ale nemá přiřazen reprezentující obrázek v tomto jazyce. Bude tedy použit anglický obrázek.`,
  _ = `E-mail je lokalizován do jazyka %1$s a %2$s, ale nemá přiřazeny reprezentující obrázky v těchto jazycích. Bude tedy použit anglický obrázek.`,
  _ = `E-mail je lokalizován do jazyka %1$s, %2$s a dalších (%3$s) jazyků, ale nemá přiřazeny reprezentující obrázky v těchto jazycích. Bude tedy použit anglický obrázek.`,
  _ = `E-mail je lokalizován do jazyka %1$s, ale nemá přiřazen reprezentující obrázek v tomto jazyce.`,
  _ = `Příprava e-mailu`,
  _ = `Událost disponuje neuloženými změnami. Než odešlete tento e-mail, uložte samotnou událost.`,
  _ = `E-mail je připraven k odeslání. Chcete jej uzamknout pro zabránění dalším změnám? Tato možnost e-mail neodešle, pouze jej přichystá k odeslání.`,
  _ = `Narazili jsme na následující upozornění. Před uzamčením obsahu e-mailu je můžete ještě opravit.`,
  _ = `Během přípravy e-mailu jsme narazili na následující chyby, které brání v jeho odeslání:`,
  _ = `Počkejte prosím, dokud nebude dokončena příprava`,
  _ = `Příprava byla dokončena. Až budete chtít, můžete e-mail odeslat.`,
  _ = `Kontaktovat společnost Valve, aby odeslala e-mail`,
  _ = `Testovací e-mail byl zařazen ke zpracování a brzy byste jej měli obdržet.`,
