  _ = `Zarovnat médium svisle na střed`,
  _ = `Zarovnat médium svisle dolů`,
  _ = `Umožňuje zvětšit odsazení z levé strany.`,
  _ = `Umožňuje zvětšit odsazení rovnoměrně z obou stran.`,
  _ = `Umožňuje zvětšit odsazení z pravé strany.`,
  _ = `Zobrazit snímek`,
  _ = `Zobrazit mikro-upoutávku`,
  _ = `Zobrazit snímek a po najetí myší mikro-upoutávku`,
  _ = `Tlačítko pro přehrání upoutávky`,
  _ = `Barva tlačítka pro přehrání`,
  _ = `Určuje barvu tlačítka pro přehrání. Vztahuje se na všechny upoutávky v této sekci. Chcete-li použít výchozí barvu, nic neměňte.`,
  _ = `Barva tlačítka pro přehrání po najetí myší`,
  _ = `Určuje barvu tlačítka pro přehrání, zatímco na něj zákazník míří myší. Vztahuje se na všechny upoutávky v této sekci. Chcete-li použít výchozí barvu, nic neměňte.`,
  _ = `Výchozí zobrazení upoutávky`,
  _ = `Určuje, jak má médium vypadat, než na něj zákazník klikne. Buď se může zobrazovat snímek z upoutávky, zacyklená mikro-upoutávka, nebo snímek a po najetí myší zacyklená mikro-upoutávka. Ať už je vybráno kterékoli zobrazení, po kliknutí se v dialogovém okně přehraje samotná upoutávka.`,
  _ = `Poměr stran`,
  _ = `16:9`,
  _ = `Poměr šířky ku výšce obrázku, aby mu stránka mohla „podržet“ místo, než se načte. Poměr stran je zaznamenán při nahrání obrázku. Pro obrázky nahrané dříve ho můžete zadat ručně.`,
  _ = `Zjistit velikost`,
