  _ = `Škálování textu`,
  _ = `Umožňuje nastavit odsazení textu mezi %1$s a %2$s (výchozí hodnota je %3$s).`,
  _ = `Resetovat škálování`,
  _ = `Sem přetáhněte obrázky (PNG/JPG/GIF/WebP) nebo videa (MP4) o velikosti nejvýše 20 MB`,
  _ = `Sem přetáhněte statické obrázky (PNG/JPG) o velikosti nejvýše 20 MB`,
  _ = `Zakáže mobilní verzi a odstraní její data.`,
  _ = `Mobilní verze je volitelné nastavení, které umožňuje plné přizpůsobení této mřížky médií (včetně možnosti poskytnout odlišný text, grafické prvky a ovládací prvky) pro zobrazení na mobilních zařízeních. `,
  _ = `Opravdu chcete zakázat mobilní verzi? Zároveň dojde k odstranění jejích dat, přičemž tuto akci nelze vzít zpět.`,
  _ = `Zakáže tabletovou verzi a odstraní její data.`,
  _ = `Tabletová verze je volitelné nastavení, které umožňuje plné přizpůsobení této mřížky médií (včetně možnosti poskytnout odlišný text, grafické prvky a ovládací prvky) pro zobrazení na tabletech, zařízení Steam Deck a podobných zařízeních.`,
  _ = `Opravdu chcete zakázat tabletovou verzi? Zároveň dojde k odstranění jejích dat, přičemž tuto akci nelze vzít zpět.`,
  _ = `Výchozí zobrazení`,
  _ = `Zobrazení pro mobil`,
  _ = `Zobrazení pro tablet`,
  _ = `Zarovnat textovou sekci svisle`,
  _ = `Umožňuje svislé zarovnání textu, když je kratší než médium nebo jiné prvky řádky.`,
  _ = `Ve zkopírované sekci existuje %1$s médií. Chcete je také přesunout do tohoto editoru?`,
  _ = `Testování existence médií (%1$s/%2$s).`,
  _ = `Stahování chybějících médií (%1$s/%2$s).`,
  _ = `Nahrávání a konvertování médií (%1$s/%2$s).`,
