  _ = `Nelze odstranit poslední zbývající obsah`,
  _ = `Editor postupu odznaku`,
  _ = `Definujte postup odznaku výprodeje a pro vyplnění aktuálního stavu použijte BBCode [badgeNextLevel eventbadgeid=#].`,
  _ = `Název odznaku`,
  _ = `Prvotní popis odznaku`,
  _ = `Popište uživatelům, kteří odznak ještě nemají, jak ho mohou získat. Tyto informace uvidí i nepřihlášení uživatelé, nicméně ti se budou muset pro získání odznaku nejprve přihlásit.`,
  _ = `Pokyny pro postup odznaku`,
  _ = `Zde můžete navrhnout dodatečné kroky, jak odznak vylepšit na další úroveň. Tyto informace budou zobrazeny uživatelům, kteří už mají základní úroveň odznaku.`,
  _ = `Pokyny pro postup odznaku (max. úroveň)`,
  _ = `Tento popis se zobrazí po vylepšení odznaku na úroveň, kterou lze pro běžného uživatele považovat za maximální dosažitelnou. Pokyny zde mohou navrhovat další akce, jak pokračovat ve vylepšování odznaku (je-li to možné).`,
  _ = `Úrovně odznaku a URL adresy`,
  _ = `Počet úrovní`,
  _ = `URL obrázku odznaku`,
  _ = `Tento prvek už nejspíš existuje v komunitě služby Steam a měl by mít rozměry 160×160 pixelů. Jako URL můžete použít zkrácenou verzi „{IMG_URL}/badges/...“.`,
  _ = `URL obrázku tajemného odznaku (volitelné)`,
  _ = `Volitelný prvek, který může být zobrazen uživateli PŘEDTÍM, než získá skutečný odznak. Hodí se, když chcete vzhled odznaku udržet v tajnosti. Prvek by měl mít rozměry 160×160 pixelů.`,
  _ = `Přidat úroveň a řádku pro URL adresu`,
  _ = `ID odznaku uživatele (specifické pro událost)`,
  _ = `Poskytování úrovní odznaku za dokončování fronty doporučení na stránce výprodeje`,
  _ = `Tato možnost očekává, že na stránce výprodeje existuje fronta doporučení. Odznak je poté dynamicky aktualizován vždy po jejím dokončení a změna je zanesena také do souhrnu fronty doporučení.`,
  _ = `Editor postupu úkolu`,
  _ = `Určuje sekci, ve které se na základě postupu úkolu může zobrazit různý obsah (resp. BBCode).`,
  _ = `Pokud je tato možnost povolena, zavřené dveře budou ukázány teprve po otevření předchozích`,
  _ = `Sekce s postupem úkolu`,
  _ = `Přidat sekci s úkolem`,
  _ = `Předřadit sekci s úkolem`,
  _ = `Index dveří úkolu – %1$s`,
  _ = `Sekce s úkolem`,
  _ = `Popište stav před splněním zadání (stav „zavřených dveří“)`,
  _ = `Popište stav po splnění zadání (stav „otevřených dveří“)`,
  _ = `Níže lze pomocí BBCode vytvořit sekci, která se objeví pouze poté, co uživatel dokončil úkol.`,
  _ = `Upravit zprávu po úspěšném dokončení`,
  _ = `Editor poličky odměn úkolu`,
  _ = `Editor umožňující přiřadit události pro získání virtuálních položek k vybraným odměnám, které uvidí uživatelé. Lze nahrát dostupné odměny a určit, které se zobrazí na seznamu.`,
  _ = `ID události pro získání virtuální položky`,
  _ = `Například: „k_EVirtualItemRewardEvent...“ (hodnota).`,
  _ = `Poslední synchronizace: `,
  _ = `URL obrázku skryté odměny (??×?? px):`,
  _ = `Obrázek, který bude použit předtím, než dojde k získání odměny. Může se jednat o tajemnou (tzn. rozostřenou, zamazanou,...) verzi skutečné položky.`,
  _ = `URL obrázku skrytého odznaku (??×?? px):`,
  _ = `Obrázek, který bude použit předtím, než dojde k získání odznaku. Může se jednat o tajemnou (tzn. rozostřenou, zamazanou,...) verzi skutečného odznaku.`,
  _ = `Seznam odměn`,
  _ = `Uděleno po otevření %1$s. dveří`,
  _ = `Ve skupině položek %1$s.`,
  _ = `Skupina položek`,
  _ = `Skupina, do které patří tato položka. Otevření dveří se rovná udělení jedné položky z každé skupiny, kterou pokrývají, takže pokud skupina skýtá více než jednu položku, je udělena jedna náhodná. Pokud položky nemají být alternativami jedna ke druhé, každou dejte do vlastní skupiny.`,
  _ = `Odznak „%1$s“ a %2$s. úroveň`,
  _ = `Přeskočit synchronizování odznaků`,
  _ = `Přidat položky mezi odměny`,
  _ = `Poznámka: Pokud je položka získatelná z věrnostního obchodu, skupinu nechte na nule. Tento mechanismus počítá pouze se skupinou nula a nesouvisí s odměnami dveří níže.`,
  _ = `ID aplikace se zveřejněnými položkami (komunitní a z věrnostního obchodu)`,
  _ = `Nebyly načteny žádné položky`,
  _ = `Virtuální položky pro %1$s`,
  _ = `Označit virtuální položku jako neaktivní odměnu`,
  _ = `Touto možností zamezíte v tom, aby byla tato položka udělována uživatelům. Již udělené položky nebudou odstraněny, nicméně bude zabráněno jakémukoli budoucímu udělení ve spojení s touto událostí/minihrou. Opravdu chcete pokračovat?`,
  _ = `Zobrazovat pouze udělené odměny`,
  _ = `Tato možnost najde využití v případech, kdy existuje více odměn, ale uživatel je za dokončení úkolu/minihry nezíská všechny.`,
  _ = `Volitelný popis odměny`,
  _ = `Tento text bude zobrazen vedle položky. Hodí se, pokud je položka udělena za dokončení úkolu a k poskytnutí kontextu ohledně odměn.`,
  _ = `Tato položka není v tuto chvíli aktivní. Zajistěte, aby před zahájením události byla vydána související aplikace a zveřejněny její komunitní položky.`,
  _ = `Skrýt sekci`,
  _ = `Umožňuje kompletně skrýt tuto sekci, takže ji zákazníci neuvidí.`,
  _ = `Zakázat sekci se zprávou „Potýkáme se s technickými problémy“`,
  _ = `Umožňuje zakázat sekci a přidat jí zprávu upozorňující na technické problémy. Nadpis a použité styly sekce budou nadále viditelné.`,
  _ = `Zakázat import/export lokalizace této sekce`,
  _ = `Umožňuje zakázat import/export obsahu této sekce. Hodí se například, když jsou pro lokalizaci používány tokeny.`,
