  _ = `Problém se službou Steam?`,
  _ = `Využijte našeho průvodce řešením problémů a získejte pomoc na míru.`,
  _ = `Získat pomoc`,
  _ = `Pomoc od komunity`,
  _ = `Váš problém už možná vyřešili ostatní uživatelé. A jestli ne, zeptejte se jich.`,
  _ = `Navštívit diskuzní fóra`,
  _ = `Nadpis stránky`,
