  _ = `Náhled stránky:`,
  _ = `Tuto stránku se nám nepodařilo najít.`,
  _ = `Přejít na panel správce`,
  _ = `Vyberte jeden nebo více souborů, které chcete nahrát a importovat z nich lokalizační data pro nadpis a tělo stránky. Pro určení formátu souboru (XML nebo CSV) používáme jeho koncovku, přičemž pokud je u souboru formátu XML před koncovkou uveden kód jazyka, budeme brát, že obsah souboru je v tomto jazyce. Ze všeho nejdříve doporučujeme exportovat jeden soubor CSV nebo XML – když budete data měnit v něm, budete mít zajištěnou správnost formátování.`,
  _ = `Tato možnost exportuje aktuálně vybraný jazyk do jednoho souboru určeného formátu. Zatímco formát XML vždy vytvoří jeden soubor s aktuálně vybraným jazykem, formát CSV do jednoho souboru exportuje všechny dostupné jazyky.`,
  _ = `Obrázky`,
  _ = `Upravit stránku`,
  _ = `Odstranit stránku...`,
  _ = `Touto možností natrvalo odstraníte tuto stránku nápovědy.`,
  _ = `Odstranění stránky nápovědy je okamžitý a nevratný proces. Opravdu tedy chcete odstranit tuto stránku a veškerý její lokalizovaný obsah?`,
  _ = `Probíhá odstranění, čekejte prosím.`,
  _ = `Odstranění bylo dokončeno. Zavřením tohoto okna se vrátíte na panel správce.`,
  _ = `Změnit viditelnost`,
  _ = `Upravit...`,
  _ = `Zde můžete změnit viditelnost této stránky nápovědy v jednotlivých službách (Steam a Steam China). Pozor, aby byla stránka dostupná v dané službě, musí být zveřejněna její verze s požadovaným jazykem nebo být dostupná její záložní verze vhodná pro danou službu.`,
  _ = `Pomocí tohoto dialogového okna můžete změnit viditelnost stránky nápovědy v jednotlivých službách (Steam a Steam China). Pokud stránka není viditelná, nebude dostupná ani po zveřejnění.`,
  _ = `Probíhá aktualizování nastavení viditelnosti.`,
