  _ = `Poznámka: Aby byl obsah viditelný ve službě Steam China, musí být lokalizovaný a zveřejněný v jazyce „Zjednodušená čínština“ nebo „Zjednodušená čínština (Steam China)“.`,
  _ = `Zobrazit veřejnou verzi`,
  _ = `Změnit interní název stránky`,
  _ = `Změna interního názvu stránky nápovědy (který vidí pouze editoři) bude použita okamžitě po kliknutí na tlačítko „OK“.`,
  _ = `Zveřejnit...`,
  _ = `Touto možností zveřejníte koncept stránky pro jeden nebo více jazyků. Poznámka: Viditelnost je ovládána odděleně.`,
  _ = `Před zveřejněním musíte koncept nejprve uložit.`,
  _ = `Probíhá zveřejnění, čekejte prosím.`,
  _ = `Zveřejnění bylo úspěšně dokončeno.`,
  _ = `Zveřejněním je daný koncept změněn ve veřejnou verzi. Následující jazyky disponují změnami v konceptu. Vyberte, které z jazyků chcete nyní zveřejnit.`,
  _ = `Poznámka: Zveřejnění je nezávislé na viditelnosti. Viditelnost tedy musíte nastavit odděleně.`,
  _ = `Při načítání došlo k chybě, protože chybí vyžadované informace o dřívějším zveřejnění. Obnovte tuto stránku.`,
